import{z as B,x as A,o as r,c as d,q as s,j as l,D as e,d as t,s as n,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"胶厚选择与反射控制","description":"","frontmatter":{"title":"胶厚选择与反射控制","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-thickness-selection.md","filePath":"litho/resist-thickness-selection.md","lastUpdated":1791063341000}'),p={name:"litho/resist-thickness-selection.md"};function D(C,a,m,h,T,c){const i=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=s('<h1 id="胶厚选择与反射控制" tabindex="-1">胶厚选择与反射控制 <a class="header-anchor" href="#胶厚选择与反射控制" aria-label="Permalink to &quot;胶厚选择与反射控制&quot;">​</a></h1><div class="epigraph"><p>工作点要落在摆动曲线斜率接近零的地方，同时满足刻蚀掩模厚度与高宽比；减反把振幅压小，选厚才有窗口。</p><footer>—— Mack 对 swing 工作点与 BARC 的论述；刻蚀掩模预算见 Levinson 一类工艺讨论</footer></div><p><a href="/litho/swing-curve">上一课</a>画出了 CD\\((d)\\)。缺口是：<strong>在曲线上落哪一点</strong>，以及反射控制与选厚谁先谁后。本课钉工作点与约束，不展开 TARC 配方（下一课）也不展开多层 BARC 结构。不把选厚写成「越薄分辨率越好」的 \\(k_1\\) 叙事。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>摆动的极值处 \\(d\\mathrm{CD}/dd\\approx 0\\)，涂覆公差对 CD 最不敏感——这是光学选厚的第一判据。极值有多个，还要满足：作为刻蚀掩模够厚、不倒塌的高宽比、光学密度（EUV 吸收）够、与 BARC 开口刻蚀的选择比。只盯第一个反射零点，可能落到刻蚀穿通或倒塌区。</p><p><span class="marginnote">直觉类比：摆动曲线像在颠簸路面找停车位——极值是平坡，涂胶的「颠簸」不会变成 CD 晃动；停在斜坡上，路一颠位置就滑。减反是把路面铺平（振幅变小），不是教你更准地踩点。</span></p><p>反射控制（压 \\(|r|\\)、压顶面反射）决定振幅。振幅大时，即使落在极值，峰谷之间的 CD 差仍可能大于规格，极值也不安全。顺序应是：先把振幅压进预算，再在剩余曲线上选斜率平坦且满足膜厚的点。</p><h3 id="薄胶不是免费的分辨率" tabindex="-1">薄胶不是免费的分辨率 <a class="header-anchor" href="#薄胶不是免费的分辨率" aria-label="Permalink to &quot;薄胶不是免费的分辨率&quot;">​</a></h3><p>胶薄，驻波节点少、有时对比积分更好，EUV 还减随机体积——但刻蚀预算先死。光学选厚不能无视转印。主干倒塌、BARC 开口刻蚀课管轨道与刻蚀；本课只要求选厚表上必须有一行「刻蚀最小厚度」。</p><p><span class="marginnote">同一光学极值，正胶与负胶、明场与暗场的 CD 斜率符号可不同，工作点要按该层的 \\(E_\\mathrm{size}\\) 定义重测，不能抄上一层的纳米厚度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测或算 CD\\((d)\\)（或 NILS\\((d)\\)、\\(E_\\mathrm{size}(d)\\)），标出极值。叠涂覆 \\(3\\sigma\\)、台阶局域厚度（后课形貌）。若涂覆公差 × 斜率 &gt; CD 规格，回退去减反，而不是把极值「选得更准」。BARC 厚度同样有自己的减反极值，要与胶厚联立：改 BARC 会平移胶的 swing 相位。</p><p>浸没与干式顶面不同，工作点不能共用一张表。换波长更是整张重做：周期 \\(\\propto\\lambda/n\\)。</p>',13)),(r(),l(o,null,{default:e(()=>[n(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20AMP%5B%22%E5%85%88%E5%8E%8B%E6%91%86%E5%8A%A8%E6%8C%AF%E5%B9%85%22%5D%20--%3E%20FLAT%5B%22%E5%86%8D%E9%80%89%20dCD%2Fdd%20%E2%89%88%200%22%5D%0A%20%20ET%5B%22%E5%88%BB%E8%9A%80%E6%9C%80%E5%B0%8F%E5%8E%9A%E5%BA%A6%22%5D%20--%3E%20PICK%5B%22%E5%B7%A5%E4%BD%9C%E7%82%B9%22%5D%0A%20%20FLAT%20--%3E%20PICK%0A%20%20AR%5B%22%E9%AB%98%E5%AE%BD%E6%AF%94%20%2F%20%E5%80%92%E5%A1%8C%22%5D%20--%3E%20PICK%0A%20%20COAT%5B%22%E6%B6%82%E8%A6%86%E5%85%AC%E5%B7%AE%22%5D%20--%3E%20CHECK%5B%22%E6%98%AF%E5%90%A6%E4%BB%8D%E5%87%BA%E8%A7%84%E6%A0%BC%22%5D%0A%20%20PICK%20--%3E%20CHECK%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h3",{id:"与-epe-预算的接口",tabindex:"-1"},[t("与 EPE 预算的接口 "),E("a",{class:"header-anchor",href:"#与-epe-预算的接口","aria-label":'Permalink to "与 EPE 预算的接口"'},"​")],-1)),a[4]||(a[4]=E("p",null,"选厚失败表现为全片 CD 随涂胶指纹走，EPE 的光学行出现与场无关、与涂覆径向指纹相关的分量。这与镜头场曲不同：改 BARC 或改目标 \\(d\\)，涂覆指纹项先动；改调平，场曲项先动。",-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"极值来自往返相位的驻点：厚度微扰不改一阶耦合。减反降低 \\(|r|\\)，把余弦项的振幅掐掉，曲线变平，极值附近的二阶也变小，窗口变宽。若只加剂量把平均 CD 拉回，工作点仍在斜坡上，涂覆一漂 CD 照样走——剂量环与选厚不互替。",-1)),(r(),l(o,null,{default:e(()=>[n(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E5%B0%84%E5%85%89%22%5D%20--%3E%20TOP%5B%22%E9%A1%B6%E9%9D%A2%E5%8F%8D%E5%B0%84%20r1%22%5D%0A%20%20IN%20--%3E%20BOT%5B%22%E5%BA%95%E9%9D%A2%E5%8F%8D%E5%B0%84%20r2%22%5D%0A%20%20TOP%20--%3E%20INTERF%5B%22%E5%BE%80%E8%BF%94%E7%9B%B8%E4%BD%8D%E5%B9%B2%E6%B6%89%20%E2%86%92%20%E6%91%86%E5%8A%A8%22%5D%0A%20%20BOT%20--%3E%20INTERF%0A%20%20INTERF%20--%3E%20EXT%5B%22%E9%A9%BB%E7%82%B9%3A%20dCD%2Fdd%20%E2%89%88%200%22%5D%0A%20%20RAMP%5B%22%E9%9D%9E%E9%A9%BB%E7%82%B9%E6%96%9C%E5%9D%A1%22%5D%20--%3E%20DOSE%5B%22%E5%8A%A0%E5%89%82%E9%87%8F%E6%8B%89%E5%B9%B3%E5%9D%87%20CD%22%5D%0A%20%20DOSE%20--%3E%20STILL%5B%22%E6%96%9C%E7%8E%87%E4%B8%8D%E5%8F%98%20%E2%86%92%20%E6%B6%82%E8%A6%86%E4%B8%80%E6%BC%82%20CD%20%E7%85%A7%E8%B5%B0%22%5D%0A%20%20BARC%5B%22%E5%87%8F%E5%8F%8D%E5%8E%8B%20%7Cr%7C%22%5D%20--%3E%20FLAT%5B%22%E6%8C%AF%E5%B9%85%E6%8E%90%E6%8E%89%20%E2%86%92%20%E6%9B%B2%E7%BA%BF%E5%8F%98%E5%B9%B3%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不指定 193 nm 或 EUV 的「标准胶厚」。金属氧化物胶、干法显影胶的光学 \\(n\\) 不同，周期另测。禁止用未公开的某厂厚度窗口当课文数据。TARC 会再改顶面振幅，选厚与 TARC 联立，细节下一课；本课只保留「顶头未压时极值仍可能不够平」。</p><p><span class="marginnote">数字实例：193 nm 干式、胶 \\(n\\approx 1.7\\)，摆动周期约 \\(\\lambda/(2n)\\approx 57\\) nm，相邻两个极值就隔这么远。若工作点落在极值处，厚度扰动的一阶项为零，CD 只随二阶小量漂——这就是「斜率平坦」换来的涂覆公差。</span></p><p><span class="marginnote">常见误区：「胶越薄分辨率越好，那就用最薄的。」刻蚀需要胶撑住整层转移，太薄直接穿通；太厚又先碰倒塌约束。选厚是在「光学平坦、刻蚀够厚、力学不倒」三个约束的交集里挑，不是单项最优。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>先减反压振幅，再选摆动极值，并满足刻蚀与倒塌。</li><li>剂量闭环不替代选厚；换波长 / 浸没必须重选。</li><li>BARC 厚与胶厚联立，相位耦合。</li><li>涂覆指纹进 EPE 时，先查工作点斜率。</li><li>下一课：顶部抗反射单独管顶头。</li><li>出处：Mack；Levinson；Born &amp; Wolf 的薄膜周期。</li></ul>',6))])}const P=B(p,[["render",D]]);export{f as __pageData,P as default};
